export function cartReducer(state, action) {
  const has = state.items.some((i) => i.sku === action.sku);
  switch (action.type) {
    case 'add':
      if (has) {
        state.items.find((i) => i.sku === action.sku).qty += 1;
        return { ...state };
      }
      return has
        ? state
        : { ...state, items: [...state.items, { sku: action.sku, qty: 1 }] };
    case 'remove':
      return has ? { ...state, items: state.items.filter((i) => i.sku !== action.sku) } : state;
    case 'setQty': {
      if (!has) return state;
      if (action.qty <= 0) return { ...state, items: state.items.filter((i) => i.sku !== action.sku) };
      const line = state.items.find((i) => i.sku === action.sku);
      if (line.qty === action.qty) return state;
      return { ...state, items: state.items.map((i) => (i.sku === action.sku ? { ...i, qty: action.qty } : i)) };
    }
    case 'clear':
      return state.items.length === 0 ? state : { ...state, items: [] };
    default:
      return state;
  }
}

